let payload = msg.payload;
if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (err) {
        node.warn("Ошибка разбора status JSON: " + err.message);
        return null;
    }
}

if (!payload || typeof payload !== "object") {
    return null;
}

function normalizeBoard(value) {
    const text = String(value ?? "").trim().toLowerCase();
    if (text === "online") return "online";
    if (text === "offline") return "offline";
    return "unknown";
}

msg.payload = {
    wifi: !!payload.wifi,
    mqtt: !!payload.mqtt,
    board12: normalizeBoard(payload.board12),
    board13: normalizeBoard(payload.board13),
    receivedAt: new Date().toISOString()
};

return msg;

const rawValue = msg.payload;
const text = String(rawValue ?? "").trim().toLowerCase();
msg.payload = {
    online: text === "online" || text === "true" || text === "1",
    normalized: text,
    raw: rawValue,
    receivedAt: new Date().toISOString()
};
return msg;

let state = flow.get("masterOperatorState");
if (!state) {
    state = {
        board12: "unknown",
        board13: "unknown",
        wifi: "unknown",
        mqtt: "unknown",
        masterOnline: "unknown",
        lastUpdate: "ожидание данных"
    };
}

function normalizeStatus(value) {
    if (value === true) return "online";
    if (value === false) return "offline";

    const text = String(value ?? "").trim().toLowerCase();
    if (text === "online" || text === "1" || text === "true") return "online";
    if (text === "offline" || text === "0" || text === "false") return "offline";
    return "unknown";
}

function describeStatus(kind, value, title, hint) {
    const normalized = normalizeStatus(value);
    let text = "Нет данных";

    if (kind === "master") {
        if (normalized === "online") text = "На связи";
        if (normalized === "offline") text = "Нет связи";
    } else if (kind === "service") {
        if (normalized === "online") text = "Подключено";
        if (normalized === "offline") text = "Нет связи";
    } else {
        if (normalized === "online") text = "В сети";
        if (normalized === "offline") text = "Нет связи";
    }

    return {
        key: normalized,
        text,
        title,
        hint
    };
}

const payload = msg.payload;
if (payload && typeof payload === "object") {
    if (Object.prototype.hasOwnProperty.call(payload, "board12")) {
        state.board12 = normalizeStatus(payload.board12);
    }
    if (Object.prototype.hasOwnProperty.call(payload, "board13")) {
        state.board13 = normalizeStatus(payload.board13);
    }
    if (Object.prototype.hasOwnProperty.call(payload, "wifi")) {
        state.wifi = normalizeStatus(payload.wifi);
    }
    if (Object.prototype.hasOwnProperty.call(payload, "mqtt")) {
        state.mqtt = normalizeStatus(payload.mqtt);
    }
    if (Object.prototype.hasOwnProperty.call(payload, "online")) {
        state.masterOnline = normalizeStatus(payload.online);
    }
}

if (msg.topic !== "operator/init") {
    state.lastUpdate = new Date().toLocaleString("ru-RU", { hour12: false });
}

flow.set("masterOperatorState", state);

const model = {
    title: "Мастер COM12",
    subtitle: "Минимальный транспортный контур через MQTT и I2C",
    master: describeStatus("master", state.masterOnline, "Мастер", "Текущее присутствие master_com12"),
    wifi: describeStatus("service", state.wifi, "Wi-Fi", "Связь платы с локальной сетью"),
    mqtt: describeStatus("service", state.mqtt, "MQTT", "Связь платы с брокером Mosquitto"),
    board12: describeStatus("board", state.board12, "Плата 12", "Статус платы 12 по опросу master"),
    board13: describeStatus("board", state.board13, "Плата 13", "Статус платы 13 по опросу master"),
    lastUpdate: state.lastUpdate,
    topics: [
        "fyl/master_com12/status",
        "fyl/master_com12/online"
    ],
    note: "Экран обновляется автоматически при новых сообщениях status и online. Если статусы замерли, сначала проверяй MQTT и последнее время обновления."
};

function makeMsg(payload) {
    return { payload };
}

return [
    makeMsg(model),
    makeMsg(model),
    makeMsg(model)
];

format:
.page-master-com12 {
  background: #f3eee5;
}

.master-hero {
  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
  background: linear-gradient(135deg, #f8f2e8 0%, #d9efe6 100%);
  border: 1px solid rgba(18, 44, 38, 0.08);
  border-radius: 24px;
  box-shadow: 0 18px 40px rgba(40, 56, 49, 0.12);
  color: #17352d;
  padding: 24px;
}

.master-hero__header {
  align-items: start;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
}

.master-eyebrow,
.diag-card__eyebrow,
.board-card__kicker {
  color: #4e6a61;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.master-hero h2,
.diag-card h3,
.board-card__title {
  margin: 0;
}

.master-hero h2 {
  font-size: 2rem;
  line-height: 1.1;
  margin-top: 8px;
}

.master-hero p {
  color: #456259;
  font-size: 1rem;
  margin: 10px 0 0;
  max-width: 640px;
}

.master-timestamp {
  background: rgba(255, 255, 255, 0.68);
  border: 1px solid rgba(18, 44, 38, 0.08);
  border-radius: 18px;
  min-width: 220px;
  padding: 14px 16px;
}

.master-timestamp span,
.diag-list__label {
  color: #5b7169;
  display: block;
  font-size: 0.82rem;
  margin-bottom: 6px;
}

.master-timestamp strong {
  font-size: 1.05rem;
}

.master-chip-grid,
.board-grid {
  display: grid;
  gap: 14px;
  margin-top: 18px;
}

.master-chip-grid {
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
}

.board-grid {
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.master-chip-card,
.board-card,
.diag-card {
  background: #fffdf9;
  border: 1px solid #ddd4c6;
  border-radius: 20px;
  box-shadow: 0 10px 24px rgba(28, 36, 33, 0.07);
}

.master-chip-card {
  padding: 16px 18px;
}

.master-chip-card__label {
  color: #536b63;
  display: block;
  font-size: 0.82rem;
  margin-bottom: 10px;
}

.master-chip {
  align-items: center;
  border-radius: 999px;
  display: inline-flex;
  font-size: 0.95rem;
  font-weight: 700;
  gap: 10px;
  padding: 7px 14px;
}

.master-chip::before,
.board-card__state::before {
  background: currentColor;
  border-radius: 50%;
  content: "";
  display: inline-block;
  flex: 0 0 auto;
}

.master-chip::before {
  height: 10px;
  width: 10px;
}

.board-card {
  padding: 20px;
}

.board-card__state {
  align-items: center;
  display: inline-flex;
  font-size: 1.5rem;
  font-weight: 700;
  gap: 12px;
  margin-top: 16px;
}

.board-card__state::before {
  height: 12px;
  width: 12px;
}

.board-card__hint {
  color: #5c6f67;
  margin: 14px 0 0;
}

.diag-card {
  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
  padding: 20px;
}

.diag-card__header {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}

.diag-badge {
  background: #e7f2ee;
  border: 1px solid #b9d7cc;
  border-radius: 999px;
  color: #1d5f4d;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 6px 12px;
}

.diag-list {
  display: grid;
  gap: 12px;
  list-style: none;
  margin: 18px 0 0;
  padding: 0;
}

.diag-list li {
  background: #f7f2ea;
  border-radius: 14px;
  padding: 12px 14px;
}

.diag-topic {
  background: #edf3f0;
  border-radius: 10px;
  color: #214e41;
  display: inline-block;
  font-family: Consolas, "Courier New", monospace;
  font-size: 0.9rem;
  margin-top: 4px;
  padding: 4px 8px;
}

.diag-card__note {
  color: #536961;
  margin: 16px 0 0;
}

.is-online {
  background: #e4f7eb;
  border-color: #b8e1c6;
  color: #0e7b56;
}

.is-offline {
  background: #fde9e8;
  border-color: #f2c2bf;
  color: #bb4a43;
}

.is-unknown {
  background: #f3efdf;
  border-color: #ddd3a8;
  color: #8d7425;
}

@media (max-width: 720px) {
  .master-hero {
    padding: 18px;
  }

  .master-hero h2 {
    font-size: 1.6rem;
  }

  .master-timestamp {
    width: 100%;
  }
}
